package com.gathin.tvhome;
import android.app.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;
final class SessionWifiUi {
 private static TextView label(Activity a,String value){TextView t=new TextView(a);t.setText(value);t.setTextSize(17);t.setTextColor(0xffd5dbe2);t.setPadding(0,12,0,4);return t;}
 private static EditText field(Activity a,LinearLayout box,String title,boolean secret){box.addView(label(a,title));EditText e=new EditText(a);e.setSingleLine(true);e.setTextColor(0xfff5f5fa);e.setHintTextColor(0xffd5dbe2);e.setSaveEnabled(false);if(secret)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(e);return e;}
 static void show(Activity a,String initialName,Runnable refresh){if(!SessionSettingsUi.ready(a))return;SessionSettingsUi.read(a,SettingsSessionClient.NETWORK_FEATURES,new Bundle(),features->{
  LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(32,12,32,12);EditText name=field(a,box,"Network name",false);if(initialName!=null)name.setText(initialName);
  ArrayList<String> ids=new ArrayList<>(Arrays.asList("OPEN","WPA2")),labels=new ArrayList<>(Arrays.asList("Open","WPA2 Personal"));if(features.getBoolean("sae")){ids.add("WPA3");labels.add("WPA3 Personal");}if(features.getBoolean("owe")){ids.add("OWE");labels.add("Enhanced Open (OWE)");}ids.addAll(Arrays.asList("PEAP","TTLS","WEP"));labels.addAll(Arrays.asList("Enterprise PEAP / MSCHAPv2","Enterprise TTLS / MSCHAPv2","WEP (legacy)"));box.addView(label(a,"Security"));Button security=new Button(a);security.setAllCaps(false);security.setTextSize(18);security.setTextColor(a.getColorStateList(R.color.settings_popup_text));security.setBackgroundResource(R.drawable.settings_popup_choice_bg);security.setPadding(20,12,20,12);security.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);box.addView(security);final int[] selected={1};
  EditText password=field(a,box,"Password / key",true);CheckBox show=new CheckBox(a);show.setText("Show password");show.setTextColor(0xfff5f5fa);show.setOnCheckedChangeListener((button,on)->password.setInputType(InputType.TYPE_CLASS_TEXT|(on?InputType.TYPE_TEXT_VARIATION_VISIBLE_PASSWORD:InputType.TYPE_TEXT_VARIATION_PASSWORD)));box.addView(show);
  LinearLayout enterprise=new LinearLayout(a);enterprise.setOrientation(LinearLayout.VERTICAL);EditText identity=field(a,enterprise,"Identity",false),anonymous=field(a,enterprise,"Anonymous identity (optional)",false),domain=field(a,enterprise,"Authentication-server domain",false);enterprise.addView(label(a,"Trust: system CA certificates. Server-domain verification is required."));box.addView(enterprise);
  enterprise.setVisibility(View.GONE);ScrollView scroll=new ScrollView(a);scroll.addView(box);java.util.function.IntConsumer choose=position->{selected[0]=position;security.setText(labels.get(position));String mode=ids.get(position);boolean secured=!mode.equals("OPEN")&&!mode.equals("OWE");password.setEnabled(secured);show.setEnabled(secured);boolean company=mode.equals("PEAP")||mode.equals("TTLS");enterprise.setVisibility(company?View.VISIBLE:View.GONE);ViewGroup.LayoutParams params=scroll.getLayoutParams();if(params!=null){params.height=company?Math.max(200,a.getResources().getDisplayMetrics().heightPixels-Math.round(200*a.getResources().getDisplayMetrics().density)):ViewGroup.LayoutParams.WRAP_CONTENT;scroll.setLayoutParams(params);}};security.setOnClickListener(v->{AlertDialog options=new SettingsPopup.Builder(a).setTitle("Network security").setSingleChoiceItems(labels.toArray(new String[0]),selected[0],(d,w)->{choose.accept(w);d.dismiss();}).setNegativeButton("Cancel",null).create();options.show();SettingsPopup.style(options);});
  AlertDialog dialog=new SettingsPopup.Builder(a).setTitle("Add network").setView(scroll).setPositiveButton("Connect",null).setNegativeButton("Cancel",null).create();dialog.show();SettingsPopup.style(dialog);choose.accept(1);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String mode=ids.get(selected[0]);NetworkCredentials.validate(name.getText().toString(),password.getText().toString(),mode,identity.getText().toString(),domain.getText().toString());Bundle input=new Bundle();input.putString("name",name.getText().toString());input.putString("password",password.getText().toString());input.putString("security",mode);input.putString("identity",identity.getText().toString());input.putString("anonymous",anonymous.getText().toString());input.putString("domain",domain.getText().toString());dialog.dismiss();SessionSettingsUi.confirm(a,"Connect to network?","Changing networks can disconnect the computer and ADB helper.",()->SessionSettingsUi.change(a,SettingsSessionClient.ADD,input,refresh));}catch(IllegalArgumentException invalid){name.setError(invalid.getMessage());}});
 });}
 private SessionWifiUi(){}
}
